import json
from pathlib import Path
p=Path('examples/a03/P1/api-proposal.json')
x=json.loads(p.read_text(encoding='utf-8'))
methods=[
('verify_claim(reservation, *, effect_gate) -> VerifiedClaim', 'Check current CLAIMING reservation from the controlled runtime transaction and the held canonical-book gate before target fence activation.', ['ClaimReservation: ledger_id,target_key,owner_id,generation,predecessor_event_head,target_store_id,target_session_id'], 'VerifiedClaim: process-local opaque handle plus exact checked reservation identity', ['OWNER_GENERATION_STALE','CLAIM_RESERVATION_INVALID','EFFECT_GATE_REQUIRED']),
('issue_first_dispatch(intent_ref, *, owner_id, generation, plan_ref, action_id, observation_binding) -> DispatchPermit', 'Verify actual current local committed intent, active owner, RUNNING cursor, valid fresh observation binding and no other unresolved/hold; reserve one first-dispatch permit without target mutation.', ['Exact intent/plan/action and PlanObservationBinding; current owner/generation'], 'DispatchPermit: opaque runtime-issued token with ledger_id,target_key,owner_id,generation,intent_ref,obligation_id,action_digest,event-head CAS and process instance binding', ['LOCAL_INTENT_COMMIT_REQUIRED','OWNER_GENERATION_STALE','BOOK_WRITE_PAUSED','TARGET_DRIFT_HOLD','PLAN_INTERRUPTED','REPLAY_FORBIDDEN']),
('consume_first_dispatch(permit, *, effect_gate, prepared_action, target_store_id, target_session_id) -> DispatchAuthorization', 'Under the held book gate atomically revalidate current runtime state, consume the single-use permit and append DISPATCH_STARTED. Authorize only one independent target transaction.', ['Runtime-issued DispatchPermit; held BookGateLease; exact PreparedAction and target identity'], 'DispatchAuthorization: opaque one-call handle with committed dispatch-event ref and exact target/owner/generation/action/fence bindings', ['DISPATCH_PERMIT_INVALID','REPLAY_FORBIDDEN','OWNER_GENERATION_STALE','BOOK_WRITE_PAUSED','EFFECT_GATE_REQUIRED','INTENT_BINDING_MISMATCH']),
('verify_target_authorization(authorization, *, effect_gate, target_key, target_store_id, target_session_id, generation, action_digest) -> VerifiedDispatch', 'Called by controlled target immediately before its effect transaction; verify the runtime-issued authorization and current owner while the common gate stays held. Target separately checks its persisted active fence in its own transaction.', ['Opaque DispatchAuthorization and exact target/fence/action identity'], 'VerifiedDispatch: one authorized transaction descriptor; no caller boolean can substitute', ['DISPATCH_PERMIT_INVALID','OWNER_GENERATION_STALE','TARGET_SESSION_BINDING_MISMATCH','TARGET_IDENTITY_MISMATCH','EFFECT_GATE_REQUIRED']),
('verify_context(context, *, target_key, expected_ledger_id, effect_gate) -> VerifiedBookContext', 'Verify context against a fresh complete current runtime scan and immutable file/index evidence, not the supplied JSON completeness claims. Retain all old/foreign-book history while projecting only this target_key.', ['Diagnostic context plus fixed anchor/ledger identity and held gate'], 'VerifiedBookContext: opaque runtime-produced snapshot with complete event head, history, pending, pause, reservations and external IDs', ['BOOK_CONTEXT_UNVERIFIED','LEDGER_INCOMPLETE','STATE_DIRECTORY_IDENTITY_MISMATCH','OWNER_GENERATION_STALE']),
('clear_target_drift_hold(hold_id, snapshot_ref, precheck_ref, targetcheck_ref, candidate_plan_ref, *, owner_id, generation) -> ClearHoldResult', 'Read-only checks and candidate planning are allowed while TARGET_DRIFT_HOLD blocks effects. Under current transaction/gate verify new actual evidence, current target state and no unresolved save obligation, then append exact HOLD_CLEARED. This does not dispatch or reuse old resolutions.', ['Fresh actual snapshot, new PRE_APPLY/TARGET and candidate plan, exact hold event, current owner/generation'], 'ClearHoldResult: new event head and cleared exact hold_id or unchanged hold with reason', ['TARGET_CHANGED','BOOK_WRITE_PAUSED','OWNER_GENERATION_STALE','OBSERVATION_NOT_FRESH','HOLD_EVIDENCE_INVALID'])
]
x['runtime_authority_protocol']={'status':'PROPOSAL_UNIMPLEMENTED','owner':'runtime.storage; target calls public protocol only','trust_boundary':'Opaque handles are issued/verified only by the supported runtime instance and current controlled store. Serialized JSON or caller booleans are diagnostic and never authority. No protection against malicious in-process replacement is claimed.','methods':[{'signature':sig,'responsibility':desc,'inputs':ins,'outputs':outs,'failure_codes':codes} for sig,desc,ins,outs,codes in methods]}
for group in x['groups']:
    for method in group.get('proposed',[]):
        method['inputs']=[s.replace('book_id identifying the registered target', 'canonical target_key identifying the registered target').replace('Requested book_id', 'Requested canonical target_key') for s in method.get('inputs',[])]
        if 'PersistentMockSession.open(' in method['signature']:
            for code in ['TARGET_SCOPE_SWITCH_UNSUPPORTED','TARGET_SESSION_BINDING_MISMATCH']:
                if code not in method['failure_codes']:method['failure_codes'].append(code)
for api in x['contracts_api']:
    if api['signature'].startswith('assert_recovery_plan_ready'):
        api['failure_codes']=[s for s in api['failure_codes'] if s!='TARGET_DRIFT_HOLD']
        api['compatibility']='Pure same-scope candidate eligibility can run during runtime TARGET_DRIFT_HOLD. Only runtime effect permits are blocked by that hold; clearing it requires new evidence and current transaction, avoiding a plan/hold cycle.'
x['terminal_and_drift_protocol']['drift']='After terminal resolution, target drift is a runtime TARGET_DRIFT_HOLD. Read-only snapshot/checks and candidate planning remain allowed; RuntimeAuthority.clear_target_drift_hold validates their fresh evidence transactionally. Effect permits remain forbidden until exact hold clearance.'
with p.open('w',encoding='utf-8',newline='\n') as h:json.dump(x,h,ensure_ascii=False,indent=2);h.write('\n')
